START TRANSACTION;
INSERT INTO supplies (supply_id,supply_name,quantity,retired) VALUES (90,'Cable',4,0);
UPDATE supplies SET quantity = quantity + 1 WHERE retired = 0 AND supply_id <> 90;
DELETE FROM supplies WHERE retired = 1 AND quantity = 0;
COMMIT;
SELECT supply_id,supply_name,quantity,retired FROM supplies ORDER BY supply_id;
